SPECS={}
INSERTS=[('q-024',dict(meta='야마 · 0/0 · 야마 2011 객15 · 학습지 105쪽 원문대조 (앱에서 누락되어 추가)',
  stem='다음 설명 중 옳은 것은?',
  choices=['Astrocyte는 수초의 생화학적, 구조적 지지작용에 관여한다.','탈수초 질환은 주로 백질부위와 정맥주위의 병변이 분포한다.','Oligodendrocyte는 세포 손상이나 사망시 탐식작용에 관여한다.','Oligodendrocyte는 세포의 ion 농도를 유지하고 신경세포의 구조형성에 보조한다.','수초가 정상적으로 형성되었으나 염증등에 의해 파괴된 경우 백질 이영양증이라 한다.'],ans=[2],
  basis='Glial cell 기능과 탈수초 질환(신병수 교수님 강의록 slide 3, 8, 복원자 윤운규). 탈수초 질환 특징: 수초 파괴, axon·neuron은 상대적으로 보존, 혈관주위 염증세포 침윤, 주로 백질과 정맥주위 병변, Wallerian degeneration 없음. 수초가 유전적으로 제대로 형성되지 않으면 백질이영양증, 정상 형성 후 염증으로 파괴되면 다발성 경화증.',
  exps=['astrocyte는 neuron의 생화학적·구조적 지지. 수초 형성·지지는 oligodendrocyte·Schwann cell.','정답.','탐식작용은 microglia.','이온 농도 유지와 구조 보조는 astrocyte.','염증에 의한 수초 파괴는 다발성 경화증. 백질이영양증은 유전적으로 수초가 제대로 형성되지 않은 경우.']))]
